// This shader is based on the 2D SDF Rounded Box Shader created by Inigo Quilez
// https://iquilezles.org/articles/distfunctions2d/
// https://www.shadertoy.com/view/4llXD7

// With a small modification on the sdRoundedBox function we can have a Chamfered Box effect

// b.x = width
// b.y = height
// r.x = edge top-right  
// r.y = edge boottom-right
// r.z = edge top-left
// r.w = edge bottom-left

float sdChamferedBox( in vec2 p, in vec2 b, in vec4 r ) 
{
    float invSqrt2 = 0.70710678118;

    r.xy = (p.x>0.0)?r.xy : r.zw;
    r.x  = (p.y>0.0)?r.x  : r.y;

    vec2 q = abs(p)-b;    
    float e = q.x + q.y + r.x;
    float d = min(max(q.x,q.y),0.0) + length(max(q,0.0));

    return max(d , e * invSqrt2); //use this to preserve thickness across the length, otherwise remove 'invSqrt2'
    //return max(d , e);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec2 m = (2.0*iMouse.xy-iResolution.xy)/iResolution.y;

	vec2 si = vec2(0.9,0.6) + 0.3*cos(iTime+vec2(0,2));
    vec4 ra = 0.3 + 0.3*cos( 2.0*iTime + vec4(0,1,2,3) );
    ra = min(ra,0.60355339059 * min(si.x,si.y));

	float d = sdChamferedBox( p, si, ra );

    vec3 col = (d>0.0) ? vec3(0.9,0.6,0.3) : vec3(0.65,0.85,1.0);
	col *= 1.0 - exp(-6.0*abs(d));
	col *= 0.8 + 0.2*cos(150.0*d);
	col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.01,abs(d)) );

    if( iMouse.z>0.001 )
    {
    d = sdChamferedBox(m, si, ra );
    col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, abs(length(p-m)-abs(d))-0.0025));
    col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, length(p-m)-0.015));
    }

	fragColor = vec4(col,1.0);
}
